import 'dart:convert';
import 'dart:typed_data';

const nunitoBase64 =
    "";

List<int> convertBase64ToZipList(String base64Data) {
  final bytes = base64.decode(base64Data);
  final intList = Uint8List.fromList(bytes).toList();
  return intList.map((byte) => byte.toUnsigned(8)).toList();
}

get nunitoFont => convertBase64ToZipList(nunitoBase64);
